def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]
    if n >= 99:
        return 'D'

    opp_d = 0
    for _, b in history:
        if b == 'D':
            opp_d += 1

    opp_c = n - opp_d

    recent5_d = sum(1 for _, b in history[-5:] if b == 'D')
    recent10_d = sum(1 for _, b in history[-10:] if b == 'D')
    recent15_d = sum(1 for _, b in history[-15:] if b == 'D')

    opp_d_run = 0
    for _, b in reversed(history):
        if b == 'D':
            opp_d_run += 1
        else:
            break

    my_d_run = 0
    for a, _ in reversed(history):
        if a == 'D':
            my_d_run += 1
        else:
            break

    ret_recent = False
    nonret_recent = 0
    window = 20
    start = max(1, n - window)
    for i in range(start, n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'D':
                ret_recent = True
            else:
                nonret_recent += 1

    dd_recent = False
    dd_window = 30
    for i in range(max(0, n - dd_window), n):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_recent = True
            break

    first_len = min(10, n)
    first10_all_c = (first_len == 10 and sum(1 for _, b in history[:10] if b == 'C') == 10)

    rate_d = opp_d / float(n)
    coop6 = opp_c * 3 >= n * 2

    clear_uncoop = (
        opp_d * 5 >= n * 2
        or recent10_d >= 7
        or recent15_d >= 10
        or (opp_d_run >= 5 and recent10_d >= 4)
    )

    exploit_confirmed = (
        not clear_uncoop
        and not ret_recent
        and not dd_recent
        and last_opp == 'C'
        and nonret_recent >= 1
        and recent10_d <= 1
        and (opp_c * 2 >= n)
    )

    probe_ok = (
        not clear_uncoop
        and not ret_recent
        and not dd_recent
        and last_opp == 'C'
        and last_my == 'C'
        and n >= 14
        and recent15_d == 0
        and (
            opp_d == 0
            or (first10_all_c and opp_d <= 5)
            or opp_d <= max(2, n // 10)
        )
    )

    if last_opp == 'D':
        if clear_uncoop:
            return 'D'

        if opp_d_run == 1:
            if opp_d <= max(2, n // 5) and recent15_d <= 2:
                return 'C'
            if coop6 and recent10_d <= 1:
                return 'C'
            if opp_d <= max(1, n // 10):
                return 'C'
            return 'D'

        if opp_d_run <= 3:
            if my_d_run >= 3 and coop6 and recent10_d <= 3:
                return 'C'
            return 'D'

        if opp_d_run == 4:
            if coop6 and opp_d <= max(6, n // 3):
                return 'C'
            return 'D'

        return 'D'

    if clear_uncoop:
        return 'D'

    if exploit_confirmed:
        return 'D'

    if last_my == 'D':
        return 'C'

    if probe_ok:
        return 'D'

    suppress = ret_recent and opp_d_run == 0 and rate_d < 0.28 and (
        opp_d <= max(4, n // 5)
        or (first10_all_c and opp_d <= 6)
    )

    if not suppress and dd_recent and coop6 and rate_d < 0.30:
        suppress = True

    if not suppress and (rate_d >= 0.22 or recent10_d >= 4):
        p = rate_d * 1.4
        if recent10_d >= 4:
            p += 0.1
        if recent5_d >= 3:
            p += 0.1
        if p > 0.8:
            p = 0.8
        if rng.random() < p:
            return 'D'

    if my_d_run >= 5:
        return 'C'

    return 'C'
